理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"side\":side,\r\n    \"country\":country,\r\n    \"province\":province\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time, SUM(common_c2s_byte_num + common_s2c_byte_num) AS total_bytes, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS total_packets, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(common_sessions) AS sessions FROM metric_region WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if country?default(\'\')?trim? length gt 0> AND country = \'${country}\' </#if> <#if province?default(\'\')?trim? length gt 0> AND province = \'${province}\' </#if> AND  side = \'${side}\' GROUP BY stat_time ORDER BY stat_time ASC\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"applicationPerformanceLocationThoughput\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = new ArrayList();\r\n\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				if(key.indexOf(\"total_bytes\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"stat_time\") != -1){\r\n					tempObj[\'statTime\'] = pojo[key]\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var fields = new ArrayList();\r\n		var obj = list[0];\r\n		for(key,value in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.add(key);\r\n		}\r\n\r\n		for(i,j in fields) {\r\n			// 先按照时间排序\r\n			list.sort((a,b)=>a.statTime.asDouble()-b.statTime.asDouble());  \r\n			var key = fields[i];\r\n			var values = new ArrayList();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n\r\n			var sumValue = 0\r\n			for(i,j in list){\r\n				var pojo = list[i];\r\n				var tempArray = new ArrayList();\r\n				tempArray.add(pojo[\"statTime\"]);\r\n				tempArray.add(pojo[key]);\r\n				values.add(tempArray);\r\n				sumValue += pojo[key].asDouble();\r\n			}\r\n\r\n			list.sort((a,b)=>b[key]-a[key]);\r\n\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.type = key;\r\n			o.result.add(lineObj);\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
