rans_percent DESC&format=json&option=real-time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"side\":side,\r\n    \"country\":country,\r\n    \"province\":province\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT country_region AS country_region, <#if country?default(\'\')?trim? length gt 0> super_admin_area AS super_admin_area, <#if province?default(\'\')?trim? length gt 0> admin_area AS admin_area, </#if> </#if> ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent FROM metric_region WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND isNotNull(pkt_retrans_ratio) <#if country?default(\'\')?trim? length gt 0> <#if province?default(\'\')?trim? length gt 0> AND country_region IN (<#if country?default(\'\')?trim? length gt 0> ${country} </#if>) AND super_admin_area IN (<#if province?default(\'\')?trim? length gt 0> ${province} </#if>) AND notEmpty(admin_area) <#else>  AND country_r