re/typeHandle\' as typeHandle;\r\nimport \'@/post/object\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"cycle\":cycle,\r\n    \"type\":type,\r\n    \"q\":q\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ROUND(AVG(avg_establish_latency_ms), 4) AS establish_latency_ms_avg, ROUND(QUANTILE(avg_establish_latency_ms,0.50)) AS establish_latency_ms_p50, ROUND(QUANTILE(avg_establish_latency_ms,0.90)) AS establish_latency_ms_p90, ROUND(QUANTILE(avg_establish_latency_ms,0.95)) AS establish_latency_ms_p95, ROUND(QUANTILE(avg_establish_latency_ms,0.99)) AS establish_latency_ms_p99, ROUND(AVG(avg_http_response_latency_ms), 4) AS http_response_latency_avg, ROUND(QUANTILE(avg_http_response_latency_ms,0.50)) AS http_response_latency_p50, ROUND(QUANTILE(avg_http_response_latency_ms,0.90)) AS http_response_latency_p90, ROUND(QUANTILE(avg_http_response_latency_ms,0.95)) AS http_response_latency_p95, ROUND(QUANTILE(avg_http_response_latency_ms,0.99)) AS http_response_latency_p99, ROUND(AVG(avg_ssl_con_latency_ms), 4) AS ssl_con_latency_avg, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.50)) AS ssl_con_latency_p50, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.90)) AS ssl_con_latency_p90, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.95)) AS ssl_con_latency_p95, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.99)) AS ssl_con_latency_p99, ROUND(AVG(tcp_lostlen_ratio), 4) AS tcp_lostlen_percent_avg, ROUND(QUANTILE(tcp_lostlen_ratio,0.50), 4) AS tcp_lostlen_percent_p50, ROUND(QUANTILE(tcp_lostlen_ratio,0.90), 4) AS tcp_lostlen_percent_p90, ROUND(QUANTILE(tcp_lostlen_ratio,0.95), 4) AS tcp_lostlen_percent_p95, ROUND(QUANTILE(tcp_lostlen_ratio,0.99), 4) AS tcp_lostlen_percent_p99, ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent_avg, ROUND(QUANTILE(pkt_retrans_ratio,0.50), 4) AS pkt_retrans_percent_p50, ROUND(QUANTILE(pkt_retrans_ratio,0.90), 4) AS pkt_retrans_percent_p90, ROUND(QUANTILE(pkt_retrans_ratio,0.95), 4) AS pkt_retrans_percent_p95, ROUND(QUANTILE(pkt_retrans_ratio,0.99), 4) AS pkt_retrans_percent_p99 FROM ${tableName} WHERE <#if cycle?default(\'\')?trim? length gt 0 && cycle ==1> stat_time >= ${startTime}-${timeDiff} AND stat_time < ${endTime}-${timeDiff} <#else> stat_time >= ${startTime} AND stat_time < ${endTime} </#if><#if filter?default(\'\')?trim? length gt 0> ${filter} </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"applicationPerformanceOverviewDrilldownDimensioAllNetworkAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = objHandle(galaxyRes);\r\n\r\nreturn result;');
