String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"category\",\n          \"value\" : \"Metric\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"data\",\n      \"value\" : \"\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Object\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"single\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"0\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      } ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/single\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime}\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"cryptcyTotalTraffic\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
INSERT INTO `magic_api_file` VALUES ('/api/interface/cryptcy/挖矿事件.ms', '{\n  \"properties\" : { },\n  \"id\" : \"copy1672910101802d2473\",\n  \"script\" : null,\n  \"groupId\" : \"f4c12173d38d490d9fd40ead86cbdab6\",\n  \"name\" : \"挖矿事件\",\n  \"createTime\" : null,\n  \"updateTime\" : 1673948265381,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/eventList\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"startTime\",\n    \"value\" : \"1669886836\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1669973236\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as postHandle\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT start_time AS start_time, source_name AS source_name, destination_name AS destination_name FROM security_event WHERE start_time >= ${startTime} AND start_time < ${endTime} AND security_type=\\\'cryptomining\\\' GROUP BY start_time, source_name, destination_name ORDER BY start_time DESC\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"cryptcyEventList\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nvar url = json.cvalue;\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = http.connect(url).param(res).get().getBody();\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
INSERT INTO `magic_api_file` VALUES ('/api/interface/cryptcy/挖矿事件分布.ms', '{\n  \"properties\" : { },\n  \"id\" : \"copy1672909833840d17993\",\n  \"script\" : null,\n  \"groupId\" : \"f4c12173d38d490d9fd40ead86cbdab6\",\n  \"name\" : \"挖矿事件分布\",\n  \"createTime\" : null,\n  \"updateTime\" : 1673948264458,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/eventMap\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"startTime\",\n    \"value\" : \"1669886836\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1669973236\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as postHandle\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT destination_country AS destination_country <#if country?default(\\\'\\\')?trim? length gt 0> destination_province AS destination_province, <#if province?default(\\\'\\\')?trim? length gt 0> destination_city AS destination_city, </#if> </#if>, COUNT(*) AS count FROM security_event WHERE start_time >= ${startTime} AND start_time < ${endTime} AND security_type=\\\'cryptomining\\\' <#if country?default(\\\'\\\')?trim? length gt 0> <#if province?default(\\\'\\\')?trim? length gt 0>AND destination_country = \\\'${country}\\\' AND destination_province = \\\'${province}\\\' AND destination_city != \\\'\\\' <#else> AND destination_country = \\\'${country}\\\' AND destination_province != \\\'\\\' </#if> <#else> AND destination_country != \\\'\\\' </#if>  GROUP BY destination_country <#if country?default(\\\'\\\')?trim? length gt 0>,destination_province <#if province?default(\\\'\\\')?trim? length gt 0>,destination_city</#if></#if>\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"cryptcyEventMap\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nvar url = json.cvalue;\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = http.connect(url).param(res).get().getBody();\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
INSERT INTO `magic_api_file` VALUES ('/api/interface/cryptcy/挖矿事件统计.ms', '{\n  \"properties\" : { },\n  \"id\" : \"copy1672909751964d39206\",\n  \"script\" : null,\n  \"groupId\" : \"f4c12173d38d490d9fd40ead86cbdab6\",\n  \"name\" : \"挖矿事件统计\",\n  \"createTime\" : null,\n  \"updateTime\" : 1673948263528,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/eventStat\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"startTime\",\n    \"value\" : \"1669886836\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1669973236\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/matrix\' as postHandle\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(start_time), \\\'PT${step}S\\\',\\\'zero\\\') AS stat_time, COUNT(*) AS count FROM security_event WHERE start_time >= ${startTime} AND start_time < ${endTime} AND security_type=\\\'cryptomining\\\' GROUP BY stat_time\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"cryptcyEventStat\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nvar url = json.cvalue;\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = http.connect(url).param(res).get().getBody();\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
INSERT INTO `magic_api_file` VALUES ('/api/interface/cryptcy/挖矿流量.ms', '{\n  \"properties\" : { },\n  \"id\" : \"copy1672909635663d67828\",\n  \"script\" : null,\n  \"groupId\" : \"f4c12173d38d490d9fd40ead86cbdab6\",\n  \"name\" : \"挖矿流量\",\n  \"createTime\" : null,\n  \"updateTime\" : 1673948276427,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/traffic\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"startTime\",\n    \"value\" : \"1669886836\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1669973236\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/single\' as postHandle\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM security_event WHERE start_time >= ${startTime} AND start_time < ${endTime} AND security_type=\\\'cryptomining\\\'\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"cryptcyTraffic\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nvar url = json.cvalue;\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = http.connect(url).param(res).get().getBody();\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
INSERT INTO `magic_api_file` VALUES ('/api/interface/cryptcy/挖矿流量占比.ms', '{\n  \"properties\" : { },\n  \"id\" : \"copy1672974923147d74376\",\n  \"script\" : null,\n  \"groupId\" : \"f4c12173d38d490d9fd40ead86cbdab6\",\n  \"name\" : \"挖矿流量占比\",\n  \"createTime\" : null,\n  \"updateTime\" : 1677139416010,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/trafficPercentage\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"startTime\",\n    \"value\" : \"1669886836\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1669973236\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : \"{\\n    \\\"message\\\": \\\"Please log in to the system first\\\",\\n    \\\"code\\\": 518008,\\n    \\\"time\\\": 1677139377113\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : {\n    \"name\" : \"\",\n    \"value\" : \"\",\n    \"description\" : \"\",\n    \"required\" : false,\n    \"dataType\" : \"Object\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : \"\",\n    \"error\" : \"\",\n    \"expression\" : \"\",\n    \"children\" : [ {\n      \"name\" : \"message\",\n      \"value\" : \"Please log in to the system first\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"code\",\n      \"value\" : \"518008\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Integer\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"time\",\n      \"value\" : \"1677139377113\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Long\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as timeHandle;\r\nimport \'@/post/single\' as postHandle\r\nimport \'@get:/interface/cryptcy/traffic\' as gatTraffic;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\ntimeHandle(parameter);\r\nvar result = gatTraffic();\r\nif(result.success){         \r\n    var cryTraffic = result.data;         \r\n    parameter.traffic = cryTraffic[0][\"bytes\"];     \r\n} \r\n\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT ROUND(isNull(${traffic!0}/nullif(SUM(common_c2s_byte_num + common_s2c_byte_num),0)),4) AS traffic_percentage FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} LIMIT 1\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"cryptcyTrafficPercentage\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nvar url = json.cvalue;\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = http.connect(url).param(res).get().getBody();\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\n\r\n\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
