ption\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/public/toHump\' as toHump;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\nimport \'@/pre/typeHandle5th\' as typeHandle5th\r\nimport \'@/public/orderHandle\' as orderHandle\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"type\":type,\r\n    \"orderBy\":orderBy,\r\n    \"limit\":limit,\r\n	\"params\":params\r\n}\r\nparameter.orderBy = orderHandle(parameter.orderBy);\r\npreHandle(parameter);\r\ntypeHandle5th(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ${dimension} AS ${label}, SUM(query_num) AS query_num, SUM(internal_query_num) AS total_internal_query_num, SUM(external_query_num) AS total_external_query_num, ROUND(AVG(avg_response_latency_ms),4) AS dns_response_latency_avg, SUM(traffic_inbound_byte + traffic_outbound_byte) AS total_bytes FROM ${tableName} WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if type?default(\'\')?trim? length gt 0 && type!=\'qtype\' && type!=\'rcode\'> AND notEmpty(${dimension}) </#if><#if params?default(\'\')?trim? length gt 0> AND ${label} IN (${params})</#if> GROUP BY ${dimension} <#if orderBy?default(\'\')?trim? length gt 0> ORDER BY ${orderBy} desc <#else> ORDER BY query_num desc </#if> <#if limit?default(\'\')?trim? length gt 0> LIMIT ${limit} </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"dnsOverviewDimensionAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key == \'query_num\'){\r\n					tempObj[\'queryRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble();\r\n				}\r\n				if(key == \'total_bytes\'){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
