n\\\\nMatcher matcher = regx.matcher(parameter);\\\\r\\\\n                       ^^^^^^^^^^^^^^^^^^   at Row:17~17,Col:1~22\\\\n\\\\norderHandle(parameter);\\\\r\\\\n^^^^^^^^^^^^^^^^^^^^^^  \\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : {\n    \"name\" : \"\",\n    \"value\" : \"\",\n    \"description\" : \"\",\n    \"required\" : false,\n    \"dataType\" : \"Object\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : \"\",\n    \"error\" : \"\",\n    \"expression\" : \"\",\n    \"children\" : [ {\n      \"name\" : \"code\",\n      \"value\" : \"999\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Integer\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"time\",\n      \"value\" : \"2023-02-23 08:48:26\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"message\",\n      \"value\" : \"在java.util.regex.Pattern中找不到方法matcher(LinkedHashMap) at Row:5~5,Col:24~41\\\\n\\\\nMatcher matcher = regx.matcher(parameter);\\\\r\\\\n                       ^^^^^^^^^^^^^^^^^^   at Row:17~17,Col:1~22\\\\n\\\\norderHandle(parameter);\\\\r\\\\n^^^^^^^^^^^^^^^^^^^^^^\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\nimport \'@/public/orderHandle\' as orderHandle;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"limit\":limit,\r\n    \"order\":order\r\n}\r\nparameter.order = orderHandle(parameter.order);\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT dns_qname AS dns_qname, COUNT(*) AS query_count, ROUND(AVG(dns_response_latency_ms)) AS dns_latency, ROUND(SUM(IF(dns_rcode = 0,0,1))/COUNT(dns_rcode),4) AS response_fail_rate FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND notEmpty(dns_qname) AND common_schema_type = \'DNS\' GROUP BY dns_qname ORDER BY ${order} DESC <#if limit?default(\'\')?trim? length gt 0> Limit ${limit} </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"dnsResolveDomain\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
