Util as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/qualityOfService\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"domain\":domain,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\\\'PT${step}S\\\',\\\'zero\\\') AS stat_time,     common_client_ip AS common_client_ip,     ROUND(AVG(http_response_latency_ms)) AS http_response_latency FROM     session_record_cn WHERE     common_recv_time > ${startTime}     AND common_recv_time < ${endTime}     AND  common_client_ip IN  (         SELECT             common_client_ip         FROM             session_record_cn         WHERE             common_recv_time > ${startTime}             AND common_recv_time < ${endTime}             AND domain = \\\'${domain}\\\'             AND notEmpty(common_client_ip)         GROUP BY       common_client_ip     ORDER BY       ROUND(AVG(http_response_latency_ms))    DESC         LIMIT 10         ) GROUP BY     stat_time,     common_client_ip	\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"entityDetailDomainClientIpHttpResponseLatency\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes,\"commonClientIp\",\"httpResponseLatency\");\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
