 \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/qualityOfService\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"domain\":domain,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\\\'PT${step}S\\\',\\\'zero\\\') AS stat_time,     common_server_ip AS common_server_ip,     ROUND(AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)),4) AS sequence_gap_loss_percent FROM     session_record_cn WHERE     common_recv_time > ${startTime}     AND common_recv_time < ${endTime}     AND common_server_ip in (         SELECT             common_server_ip         FROM             session_record_cn         WHERE             common_recv_time > ${startTime}             AND common_recv_time < ${endTime}             AND domain = \\\'${domain}\\\'             AND notEmpty(common_server_ip)         GROUP BY             common_server_ip         ORDER BY             AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)) DESC         LIMIT 10         ) GROUP BY     stat_time,     common_server_ip\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"entityDetailDomainServerIpPacketLoss\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes,\"commonServerIp\",\"sequenceGapLossPercent\");\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
