\r\n    \"inParam\":inParam\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT SUM(IF( ${outParam}, traffic_outbound_byte, 0) + IF( ${inParam}, traffic_inbound_byte, 0)) as total_bytes,SUM(IF( ${outParam}, traffic_outbound_pkt, 0) + IF( ${inParam}, traffic_inbound_pkt, 0)) AS total_packets,ROUND(AVG(avg_establish_latency_ms), 4) AS establish_latency_ms,ROUND(AVG(avg_http_response_latency_ms), 4) AS http_response_latency,ROUND(AVG(avg_ssl_con_latency_ms), 4) AS ssl_con_latency,ROUND(AVG(tcp_lostlen_ratio), 4) AS tcp_lostlen_percent,ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent FROM metric_link WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"linkOverviewDrilldownNetworkAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key == \'total_bytes\'){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
