ea, IF(client_zone = \'external\' AND server_zone = \'internal\', server_super_admin_area, NULL)) AS internal_location,IF(client_zone = \'internal\' AND server_zone = \'external\', server_super_admin_area, IF(client_zone = \'external\' AND server_zone = \'internal\', client_super_admin_area, NULL)) AS external_location,out_link_direction AS out_link_direction,common_out_link_id AS common_out_link_id,SUM(traffic_outbound_byte) AS out_bytes FROM metric_link WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND notEmpty(out_link_direction) AND notEmpty(internal_location) AND notEmpty(external_location) <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if> GROUP BY internal_location,out_link_direction,common_out_link_id,external_location\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"linkOverviewDrilldownQuadrupleEgressAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key == \'out_bytes\'){\r\n					tempObj[\'outBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
