\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/qualityOfService\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\\\'PT${step}S\\\',\\\'zero\\\') AS stat_time,common_app_label AS app_name,ROUND(AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)),4) AS sequence_gap_loss_percent FROM session_record_cn WHERE common_recv_time > ${startTime} AND common_recv_time < ${endTime} AND common_app_label IN (SELECT common_app_label FROM metric_top_entity WHERE common_recv_time > ${startTime} AND common_recv_time < ${endTime} AND group_by = \\\'common_app_label\\\' AND order_by = \\\'packet_loss\\\' AND time_granularity = 60 AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG(packet_loss) DESC LIMIT 10 ) GROUP BY stat_time,common_app_label\\\",\\n    \\\"option\\\": \\\"real-time\\\",\\n    \\\"format\\\": \\\"json\\\"\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"npmAppPacketLoss\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxy