children\" : [ {\n        \"name\" : \"\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Object\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ {\n          \"name\" : \"name\",\n          \"value\" : \"pkt_retrans_avg\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"type\",\n          \"value\" : \"double\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"category\",\n          \"value\" : \"Metric\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"data\",\n      \"value\" : \"\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Object\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"table\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Array\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      } ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"country\":country\r\n}\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT ROUND(AVG(pkt_retrans_percent), 4) AS pkt_retrans_avg, ROUND(QUANTILE(pkt_retrans_percent, 0.5), 4) AS pkt_retrans_p50, ROUND(QUANTILE(pkt_retrans_percent, 0.9), 4) AS pkt_retrans_p90, ROUND(QUANTILE(pkt_retrans_percent, 0.99), 4) AS pkt_retrans_p99,<#if country?default(\\\'\\\')?trim? length gt 0> <#if region?default(\\\'\\\')?trim? length gt 0> server_region AS server_region,  </#if> server_province AS server_province, </#if> server_country AS server_country FROM( SELECT ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num),4) AS pkt_retrans_percent, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL ${step} SECOND)) AS granularity, <#if country?default(\\\'\\\')?trim? length gt 0> server_province AS server_province, <#if region?default(\\\'\\\')?trim? length gt 0> server_region AS server_region, </#if> </#if>server_country AS server_country FROM metric_map WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND common_l4_protocol IN (\\\'IPv4_TCP\\\', \\\'IPv6_TCP\\\') <#if country?default(\\\'\\\')?trim? length gt 0> <#if region?default(\\\'\\\')?trim? length gt 0> AND server_region != \\\'\\\' AND server_province = \\\'${region}\\\' AND server_country = \\\'${country}\\\' <#else> AND server_region != \\\'\\\' AND server_country = \\\'${country}\\\' </#if>  <#else> AND server_country != \\\'\\\' </#if> GROUP BY granularity,server_country<#if country?default(\\\'\\\')?trim? length gt 0>, server_province <#if region?default(\\\'\\\')?trim? length gt 0> , server_region  </#if> </#if> ) GROUP BY server_country<#if country?default(\\\'\\\')?trim? length gt 0>, server_province <#if region?default(\\\'\\\')?trim? length gt 0> , server_region  </#if> </#if> ORDER BY pkt_retrans_avg DESC\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"npmPacketRetransMap\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
