var result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes\") != -1){\r\n					tempObj[\'bitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"packets\") != -1){\r\n					tempObj[\'packetsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
