AS internal_packets, SUM(traffic_through_byte) AS through_bytes, SUM(traffic_through_pkt) AS through_packets FROM ${tableName} WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if> GROUP BY granularity ORDER BY granularity ASC\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar temp  = freeMarkerUtil.processTemplateIntoString(\"overviewTotalTrafficAnalysis\",q,parameter);\r\nvar res = jsonUtil.toBean(temp,HashMap.class);\r\nvar result = getGalaxyResult(res);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	var newList = new ArrayList();\r\n	for(i,j in list){\r\n		newList.add(list[i]);\r\n	}\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				if(key.indexOf(\"granularity\") != -1){\r\n					tempObj[\'granularity\'] = pojo[key]\r\n				}else if(key.indexOf(\"total_bytes\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"total_packets\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var bytes = [];\r\n		var packets = [];\r\n		var sessions = [];\r\n		\r\n		for(key,value in list[0]){\r\n			if(key.indexOf(\"Bits\") != -1){\r\n				bytes.push(key);\r\n			} else if(key.indexOf(\"Packets\") != -1){\r\n				packets.push(key);\r\n			} else if(key.indexOf(\"Sessions\") != -1){\r\n				sessions.push(key);\r\n			}\r\n		}\r\n		var map = new HashMap();\r\n		map.put(\"totalBitsRate\",\"total_bytes\");\r\n		map.put(\"totalPacketsRate\",\"total_packets\");\r\n		map.put(\"totalSessionsRate\",\"total_sessions\");\r\n		map.put(\"inboundBitsRate\",\"inbound_bytes\");\r\n		map.put(\"inboundPacketsRate\",\"inbound_packets\");\r\n		map.put(\"outboundBitsRate\",\"outbound_bytes\");\r\n		map.put(\"outboundPacketsRate\",\"outbound_packets\");\r\n		map.put(\"internalBitsRate\",\"internal_bytes\");\r\n		map.put(\"internalPacketsRate\",\"internal_packets\");\r\n		map.put(\"throughBitsRate\",\"through_bytes\");\r\n		map.put(\"throughPacketsRate\",\"through_packets\");\r\n		var type = {};\r\n		type.bytes = bytes;\r\n		type.packets = packets;\r\n		type.sessions = sessions;\r\n		\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			var typeKey = type[key];\r\n			for(m,n in typeKey){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				list.sort((a,b)=>a.granularity.asDouble()-b.granularity.asDouble());\r\n				var sumValue = 0;\r\n				for(i,j in list){\r\n					var pojo = list[i];\r\n					var tempArray = new ArrayList();\r\n					tempArray.add(pojo[\"granularity\"]);\r\n					tempArray.add(pojo[typeKey[m]].asDouble());\r\n					values.add(tempArray);\r\n				}\r\n				for(i,j in newList){\r\n					var pojo = newList[i];\r\n					var field = map.get(typeKey[m]);\r\n					var value = pojo[field];\r\n					sumValue += value.asDouble();\r\n				}\r\n				analysis.avg =  (sumValue.asDouble()/parameter.timeDiff).toFixed(2);\r\n				if(key==\"bytes\"){\r\n					analysis.avg = analysis.avg.asDouble() * 8;\r\n				}\r\n				analysis.avg=analysis.avg+\"\";\r\n				\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1].asDouble());\r\n				}\r\n				analysis.max = plist.max()+\"\";\r\n				analysis.min = plist.min()+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[typeKey[m]] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n		var len = old[0][\"totalBitsRate\"][\"values\"].length;\r\n		for(a,b in old){\r\n			if(old[a].type == \'bytes\' || old[a].type == \'packets\'){\r\n				var other = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				var sumValue = 0;\r\n				for(i in range(0,len-1)){\r\n					var sum = 0;\r\n					var tempArray = new ArrayList();\r\n					for(b,c in old[a]){\r\n						if(b != \'type\'){\r\n							if(b.indexOf(\"total\") != -1){\r\n								sum += old[a][b][\"values\"][i][1];\r\n							} else {\r\n								sum -= old[a][b][\"values\"][i][1];\r\n							}\r\n							sum = sum.asDouble() > 0 ? sum:0;\r\n						}\r\n					}\r\n					tempArray.add(old[0][\"totalBitsRate\"][\"values\"][i][0]);\r\n					tempArray.add(sum.toFixed(2).asDouble());\r\n					values.add(tempArray);\r\n					sumValue += sum.asDouble();\r\n				}\r\n				analysis.avg = ((sumValue / len)*100/100).toFixed(2) + \"\";\r\n					\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1].asDouble());\r\n				}\r\n				analysis.max = plist.max()+\"\";\r\n				analysis.min = plist.min()+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n				other.values = values;\r\n				other.analysis = analysis;\r\n				old[a].other = other;\r\n			}\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\nreturn result;');
