模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\": \\\"SELECT common_server_ip AS server_ip, SUM(common_sessions) AS sessions, SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets, SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM metric_top_entity WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND group_by = \\\'common_server_ip\\\' AND order_by = \\\'${order}\\\' AND time_granularity = 60 GROUP BY server_ip ORDER BY ${order} desc limit ${limit}\\\",\\\"option\\\": \\\"real-time\\\",\\\"format\\\": \\\"json\\\"}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"trafficActiveServerIP\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
