          \"value\" : \"stat_time\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"type\",\n          \"value\" : \"long\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"category\",\n          \"value\" : \"Dimension\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"data\",\n      \"value\" : \"\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Object\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"matrix\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Array\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ {\n          \"name\" : \"\",\n          \"value\" : \"\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"Object\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ {\n            \"name\" : \"values\",\n            \"value\" : \"\",\n            \"description\" : \"\",\n            \"required\" : false,\n            \"dataType\" : \"Array\",\n            \"type\" : null,\n            \"defaultValue\" : null,\n            \"validateType\" : \"\",\n            \"error\" : \"\",\n            \"expression\" : \"\",\n            \"children\" : [ {\n              \"name\" : \"\",\n              \"value\" : \"\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Array\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ {\n                \"name\" : \"\",\n                \"value\" : \"1689225156\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"String\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ ]\n              } ]\n            } ]\n          }, {\n            \"name\" : \"legend\",\n            \"value\" : \"bytesSentRate\",\n            \"description\" : \"\",\n            \"required\" : false,\n            \"dataType\" : \"String\",\n            \"type\" : null,\n            \"defaultValue\" : null,\n            \"validateType\" : \"\",\n            \"error\" : \"\",\n            \"expression\" : \"\",\n            \"children\" : [ ]\n          }, {\n            \"name\" : \"aggregation\",\n            \"value\" : \"\",\n            \"description\" : \"\",\n            \"required\" : false,\n            \"dataType\" : \"Object\",\n            \"type\" : null,\n            \"defaultValue\" : null,\n            \"validateType\" : \"\",\n            \"error\" : \"\",\n            \"expression\" : \"\",\n            \"children\" : [ {\n              \"name\" : \"first\",\n              \"value\" : \"0\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Integer\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            }, {\n              \"name\" : \"last\",\n              \"value\" : \"119\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Integer\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            }, {\n              \"name\" : \"avg\",\n              \"value\" : \"166.37\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"String\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            }, {\n              \"name\" : \"p50\",\n              \"value\" : \"138.0\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"String\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            }, {\n              \"name\" : \"p90\",\n              \"value\" : \"263.0\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"String\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            }, {\n              \"name\" : \"max\",\n              \"value\" : \"361.0\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"String\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            } ]\n          } ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"originalUrl\",\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT36S\',\'zero\') AS stat_time, ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num)/ 36) AS bytes_rate, ROUND(SUM(common_c2s_byte_num)/ 36) AS bytes_sent_rate, ROUND(SUM(common_s2c_byte_num)/ 36) AS bytes_received_rate FROM session_record_cn WHERE common_recv_time >= toDateTime(1689225171) AND common_recv_time < toDateTime(1689228771) AND (common_server_ip = \'38.242.7.203\' OR common_client_ip=\'38.242.7.203\') GROUP BY stat_time&format=json&option=real-time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport \'@/pre/timeHandleNone\' as timeHandle;\r\nimport \'@get:/interface/entity/detail/overview/ip/traffic\' as getIpTraffic;\r\nimport \'@get:/interface/entity/detail/overview/app/traffic\' as getAppTraffic;\r\nimport \'@get:/interface/entity/detail/overview/domain/traffic\' as getDomainTraffic;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"entityType\":entityType,\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\ntimeHandle(parameter);\r\nstartTime = parameter.startTime;\r\nendTime = parameter.endTime;\r\n\r\nvar result = {};\r\nif (\"ip\".equals(parameter.entityType)) {\r\n    var ip = parameter.resource;\r\n    result = getIpTraffic();\r\n} else if (\"app\".equals(parameter.entityType)) {\r\n    var appName = parameter.resource;\r\n    result = getAppTraffic();\r\n} else if (\"domain\".equals(parameter.entityType)) {\r\n    var domain = parameter.resource;\r\n    result = getDomainTraffic();\r\n}\r\n\r\nreturn result;');
