ll,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ {\n    \"name\" : \"cn-Authorization\",\n    \"value\" : \"cntest\",\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"paths\" : [ ],\n  \"responseBody\" : \"{\\n    \\\"status\\\": 200,\\n    \\\"code\\\": \\\"20000666\\\",\\n    \\\"queryKey\\\": \\\"afb1ded9286eaa3a9bd2799acd76c285\\\",\\n    \\\"success\\\": true,\\n    \\\"message\\\": \\\"OK\\\",\\n    \\\"statistics\\\": {\\n        \\\"elapsed\\\": 1,\\n        \\\"rows_read\\\": 1799,\\n        \\\"bytes_read\\\": 115667,\\n        \\\"result_size\\\": 0,\\n        \\\"result_rows\\\": 0\\n    },\\n    \\\"job\\\": null,\\n    \\\"formatType\\\": \\\"json\\\",\\n    \\\"meta\\\": [{\\n        \\\"name\\\": \\\"entityValue\\\",\\n        \\\"type\\\": \\\"string\\\",\\n        \\\"category\\\": \\\"Dimension\\\"\\n    }, {\\n        \\\"name\\\": \\\"entityType\\\",\\n        \\\"type\\\": \\\"string\\\",\\n        \\\"category\\\": \\\"Dimension\\\"\\n    }],\\n    \\\"data\\\": {\\n        \\\"list\\\": [],\\n        \\\"total\\\": 20,\\n        \\\"pageNo\\\": 4,\\n        \\\"pageSize\\\": 10\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/?query=SELECT arrayJoin(splitByChar(\'$\',concat(ip , \'$\', domain, \'$\', app_name))) AS entityValue, (case when ip = entityValue then \'ip\' when domain= entityValue then \'domain\' when app_name = entityValue then \'app\' else \'\' end) as entityType FROM cn_entity_relation WHERE update_time >= 16922847 AND update_time < 1692773847 AND notEmpty(entityValue)  AND (domain = \'baidu.com\')  GROUP BY entityValue,entityType ORDER BY MAX(update_time) DESC  LIMIT 30,10&format=json&option=real-time\\\"\\n}\",\n  \"description\" : null,\n  \"reques