INSERT INTO `magic_api_file` VALUES ('/api/v1/entity/explorer/top/IP-ASN-实体基数统计.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"fb874f72ba3c4c56b597beeb21e51c23\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"80392cde8e944a6e9c947b4ad8661c29\",\r\n  \"name\" : \"IP-ASN-实体基数统计\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1692846251060,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"/agg-ip-asn\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ {\r\n    \"name\" : \"resource\",\r\n    \"value\" : \"\\\"APP Category\\\" =\'param\' or Port=80 and has(Tag,\'lll\')\",\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"startTime\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"Long\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"endTime\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"Long\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"status\\\": 200,\\n    \\\"code\\\": \\\"20000666\\\",\\n    \\\"queryKey\\\": \\\"e8418bf2f06a27ed717cdbb65ee305ba\\\",\\n    \\\"success\\\": true,\\n    \\\"message\\\": \\\"OK\\\",\\n    \\\"statistics\\\": {\\n        \\\"elapsed\\\": 2,\\n        \\\"rows_read\\\": 2652,\\n        \\\"bytes_read\\\": 227891,\\n        \\\"result_size\\\": 0,\\n        \\\"result_rows\\\": 0\\n    },\\n    \\\"job\\\": null,\\n    \\\"formatType\\\": \\\"json\\\",\\n    \\\"meta\\\": [{\\n        \\\"name\\\": \\\"ip_asn\\\",\\n        \\\"type\\\": \\\"string\\\",\\n        \\\"category\\\": \\\"Dimension\\\"\\n    }, {\\n        \\\"name\\\": \\\"appCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"domainCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"ipCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"totalCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }],\\n    \\\"data\\\": {\\n        \\\"list\\\": []\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/?query=SELECT ip_asn as ip_asn, COUNTIF(DISTINCT(app_name),notEmpty(app_name)) as appCount, COUNTIF(DISTINCT(domain),notEmpty(domain)) as domainCount, COUNTIF(DISTINCT(ip),notEmpty(ip)) as ipCount, plus(ipCount,plus(appCount,domainCount)) AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.ip_asn AS ip_asn FROM cn_entity_relation e  JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip)  WHERE e.update_time >= 1677291537 AND e.update_time < 1692843537 AND notEmpty(ip_asn)  AND dr.update_time >= 1677291537 AND dr.update_time < 1692843537  AND (e.app_category = \'param\' OR dr.port = 80 AND has(e.entity_tags, \'lll\'))  ) GROUP BY ip_asn ORDER BY totalCount DESC limit 5&format=json&option=real-time\\\"\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n  