: 246637,\\n        \\\"result_size\\\": 0,\\n        \\\"result_rows\\\": 0\\n    },\\n    \\\"job\\\": null,\\n    \\\"formatType\\\": \\\"json\\\",\\n    \\\"meta\\\": [{\\n        \\\"name\\\": \\\"ip_country_region\\\",\\n        \\\"type\\\": \\\"string\\\",\\n        \\\"category\\\": \\\"Dimension\\\"\\n    }, {\\n        \\\"name\\\": \\\"appCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"domainCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"ipCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"totalCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }],\\n    \\\"data\\\": {\\n        \\\"list\\\": []\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/?query=SELECT ip_country_region as ip_country_region, COUNTIF(DISTINCT(app_name),notEmpty(app_name)) as appCount, COUNTIF(DISTINCT(domain),notEmpty(domain)) as domainCount, COUNTIF(DISTINCT(ip),notEmpty(ip)) as ipCount, plus(ipCount,plus(appCount,domainCount)) AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.ip_country_region AS ip_country_region FROM cn_entity_relation e  JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip)  WHERE e.update_time >= 1677294295 AND e.update_time < 1692846295 AND notEmpty(ip_country_region) AND dr.update_time >= 1677294295 AND dr.update_time < 1692846295 AND (e.app_category = \'param\' OR dr.port = 80 AND has(e.entity_tags, \'lll\')) ) GROUP BY ip_country_region ORDER BY totalCount DESC limit 5&format=json&option=real-time\\\"\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\