_size\\\": 0,\\n        \\\"result_rows\\\": 0\\n    },\\n    \\\"job\\\": null,\\n    \\\"formatType\\\": \\\"json\\\",\\n    \\\"meta\\\": [{\\n        \\\"name\\\": \\\"port\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Dimension\\\"\\n    }, {\\n        \\\"name\\\": \\\"l7_protocol\\\",\\n        \\\"type\\\": \\\"string\\\",\\n        \\\"category\\\": \\\"Dimension\\\"\\n    }, {\\n        \\\"name\\\": \\\"appCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"domainCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"ipCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"totalCount\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }],\\n    \\\"data\\\": {\\n        \\\"list\\\": []\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/?query=SELECT port AS port, l7_protocol AS l7_protocol, COUNTIF(DISTINCT(app_name),notEmpty(app_name)) as appCount, COUNTIF(DISTINCT(domain),notEmpty(domain)) as domainCount, COUNTIF(DISTINCT(ip),notEmpty(ip)) as ipCount, plus(ipCount,plus(appCount,domainCount)) AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.ip_admin_area AS ip_admin_area, dr.port AS port, dr.l7_protocol AS l7_protocol FROM cn_entity_relation e JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip) WHERE e.update_time >= 1677294697 AND e.update_time < 1692846697 AND dr.update_time >= 1677294697 AND dr.update_time < 1692846697  AND (dr.l7_protocol = \'HTTP\') ) GROUP BY port,l7_protocol ORDER BY totalCount DESC limit 5&format=json&option=real-time\\\"\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\