 \"defaultValue\" : null,\r\n          \"validateType\" : \"\",\r\n          \"error\" : \"\",\r\n          \"expression\" : \"\",\r\n          \"children\" : [ ]\r\n        }, {\r\n          \"name\" : \"type\",\r\n          \"value\" : \"long\",\r\n          \"description\" : \"\",\r\n          \"required\" : false,\r\n          \"dataType\" : \"String\",\r\n          \"type\" : null,\r\n          \"defaultValue\" : null,\r\n          \"validateType\" : \"\",\r\n          \"error\" : \"\",\r\n          \"expression\" : \"\",\r\n          \"children\" : [ ]\r\n        }, {\r\n          \"name\" : \"category\",\r\n          \"value\" : \"Dimension\",\r\n          \"description\" : \"\",\r\n          \"required\" : false,\r\n          \"dataType\" : \"String\",\r\n          \"type\" : null,\r\n          \"defaultValue\" : null,\r\n          \"validateType\" : \"\",\r\n          \"error\" : \"\",\r\n          \"expression\" : \"\",\r\n          \"children\" : [ ]\r\n        } ]\r\n      } ]\r\n    }, {\r\n      \"name\" : \"data\",\r\n      \"value\" : \"\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ {\r\n        \"name\" : \"list\",\r\n        \"value\" : \"\",\r\n        \"description\" : \"\",\r\n        \"required\" : false,\r\n        \"dataType\" : \"Array\",\r\n        \"type\" : null,\r\n        \"defaultValue\" : null,\r\n        \"validateType\" : \"\",\r\n        \"error\" : \"\",\r\n        \"expression\" : \"\",\r\n        \"children\" : [ ]\r\n      } ]\r\n    }, {\r\n      \"name\" : \"originalUrl\",\r\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT port AS port, l7_protocol AS l7_protocol, COUNTIF(DISTINCT(app_name),notEmpty(app_name)) as appCount, COUNTIF(DISTINCT(domain),notEmpty(domain)) as domainCount, COUNTIF(DISTINCT(ip),notEmpty(ip)) as ipCount, plus(ipCount,plus(appCount,domainCount)) AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.ip_admin_area AS ip_admin_area, dr.port AS port, dr.l7_protocol AS l7_protocol FROM cn_entity_relation e JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip) WHERE e.update_time >= 1677294697 AND e.update_time < 1692846697 AND dr.update_time >= 1677294697 AND dr.update_time < 1692846697  AND (dr.l7_protocol = \'HTTP\') ) GROUP BY port,l7_protocol ORDER BY totalCount DESC limit 5&format=json&option=real-time\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport cn.hutool.log.Log;\r\nimport cn.hutool.core.util.ObjectUtil;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport \'@/public/toHump\' as toHump;\r\nimport net.geedge.modules.entity.service.EntityExplorerService as EntityExplorerService;\r\nimport \'@/pre/timeHandleHalf\' as timeHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"dr\":false,\r\n    \"fqdnCategory\":false,\r\n    \"whois\":false,\r\n    \"appCategory\":false\r\n}\r\ntimeHandle(parameter);\r\nparameter.resource = EntityExplorerService.parseExpression(parameter.resource);\r\n/**\r\n * 如果resource表达式中涉及联表字段，将进行联表查询。例：Whois.Domain\r\n */\r\nparameter.filter = parameter.resource;\r\nvar param = EntityExplorerService.getAssociationQueryParam(parameter.resource);\r\nvar columns = [\"dr\",\"fqdnCategory\",\"whois\",\"appCategory\"];\r\nif(ObjectUtil.isNotEmpty(param)){\r\n    for (item in columns) {\r\n        for (k,v in param) {\r\n            parameter[k] = v;\r\n            if (v.asString().contains(item)){\r\n                parameter[item] = true;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n}\r\nvar isAssociationQuery = EntityExplorerService.isAssociationQuery(parameter.resource);\r\nif(isAssociationQuery){\r\n    var sql = \"{\\\"sql\\\":\\\"SELECT port AS port, l7_protocol AS l7_protocol, COUNT(DISTINCT(app_name)) FILTER (WHERE app_name != \'\') AS appCount, COUNT(DISTINCT(domain)) FILTER (WHERE domain != \'\') AS domainCount, COUNT(DISTINCT(ip)) FILTER (WHERE ip != \'\') AS ipCount, COUNT(DISTINCT(app_name)) FILTER (WHERE app_name != \'\') + COUNT(DISTINCT(domain)) FILTER (WHERE domain != \'\') + COUNT(DISTINCT(ip)) FILTER (WHERE ip != \'\') AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, dr.port AS port, dr.l7_protocol AS l7_protocol FROM clickhouse.cyber_narrator_galaxy.cn_entity_relation e JOIN clickhouse.cyber_narrator_galaxy.cn_ip_dynamic_attribute dr ON (e.ip = dr.ip AND dr.update_time >= ${startTime} AND dr.update_time < ${endTime} <#if dr\\.port?default(\'\')?trim? length gt 0> AND ${dr\\.port}</#if>) <#if fqdnCategory> JOIN mysql.cn_api.cn_fqdn_category_built_in fqdnCategory ON (e.domain = fqdnCategory.fqdn <#if fqdnCategory\\.category_name?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.category_name} </#if> <#if fqdnCategory\\.category_group?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.category_group} </#if> <#if fqdnCategory\\.reputation_level?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.reputation_level}</#if>) </#if> <#if whois> JOIN mysql.cn_api.cn_fqdn_who_is_built_in whois ON (e.domain = whois.fqdn <#if whois\\.whois_domain?default(\'\')?trim? length gt 0> AND ${whois\\.whois_domain} </#if> <#if whois\\.whois_registrant_name?default(\'\')?trim? length gt 0> AND ${whois\\.whois_registrant_name}</#if>) </#if> <#if appCategory> JOIN mysql.cn_api.cn_app_category_built_in appCategory ON (e.app_name = appCategory.app_name <#if appCategory\\.app_category?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_category} </#if> <#if appCategory\\.app_subcategory?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_subcategory} </#if> <#if appCategory\\.app_risk?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_risk}</#if>) </#if> WHERE e.update_time >= ${startTime} AND e.update_time < ${endTime} <#if filter?default(\'\')?trim? length gt 0> ${filter} </#if> ) GROUP BY port,l7_protocol ORDER BY totalCount DESC\\\"}\"\r\n    var aTemplate  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerTopAggPort\",sql,parameter);\r\n    var ares = jsonUtil.toBean(aTemplate,HashMap.class);\r\n    var log = Log.get();\r\n    log.info(ares.sql);\r\n    var aresult = db[\'trino\'].select(ares.sql);\r\n    var list=new ArrayList();\r\n    if(ObjectUtil.isNotEmpty(aresult)){\r\n        if(aresult.length > 0){\r\n            for(key,value in aresult){\r\n                var obj = {};\r\n                obj.port = value.port;\r\n                obj.l7Protocol = value.l7_protocol;\r\n                obj.uniqueEntities = value.totalCount;\r\n                list.add(obj);\r\n            }\r\n        }\r\n    }\r\n    var data = {};\r\n    data.list = list;\r\n    var url = db.select(\"select cvalue from sys_config where ckey = \'galaxy_url\'\");\r\n    return R.ok(data).put(\"originalUrl\",url.cvalue+ares.sql);\r\n}\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT port AS port, l7_protocol AS l7_protocol, COUNTIF(DISTINCT(app_name),notEmpty(app_name)) as appCount, COUNTIF(DISTINCT(domain),notEmpty(domain)) as domainCount, COUNTIF(DISTINCT(ip),notEmpty(ip)) as ipCount, plus(ipCount,plus(appCount,domainCount)) AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.ip_admin_area AS ip_admin_area, dr.port AS port, dr.l7_protocol AS l7_protocol FROM cn_entity_relation e JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip) WHERE e.update_time >= ${startTime} AND e.update_time < ${endTime}<#if dr> AND dr.update_time >= ${startTime} AND dr.update_time < ${endTime} </#if><#if filter?default(\\\'\\\')?trim? length gt 0> AND (${filter}) </#if>) GROUP BY port,l7_protocol ORDER BY totalCount DESC limit 5\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerTopAggTag\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar data = {};\r\nvar list = new ArrayList();\r\nif(result.success){\r\n    for(key,value in result.data){\r\n        var obj = {};\r\n        obj.port = value.port;\r\n        obj.l7Protocol = value.l7_protocol;\r\n        obj.uniqueEntities = value.totalCount;\r\n        list.add(obj);\r\n    }\r\n}\r\ndata.list = list;\r\nresult.data = data;\r\nreturn result;');
