Type\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"message\",\r\n      \"value\" : \"success\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport cn.hutool.log.Log;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport \'@/pre/timeHandleHalf\' as timeHandle;\r\nimport \'@/pre/pageFieldsHandle\' as pageHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\nimport net.geedge.modules.entity.service.EntityService as EntityService;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"entityType\":\"app\",\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"pageNo\":pageNo,\r\n    \"pageSize\":pageSize\r\n}\r\ntimeHandle(parameter);\r\npageHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT DISTINCT(app_name) AS app_name FROM cn_entity_relation WHERE update_time >= ${startTime} AND update_time < ${endTime} AND cutToFirstSignificantSubdomain(domain) = \\\'${resource}\\\' AND notEmpty(app_name) ORDER BY update_time DESC <#if pageSize?default(\\\'\\\')?trim? length gt 0&&pageNo?default(\\\'\\\')?trim? length gt 0> LIMIT ${pageNo},${pageSize}</#if>\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityGraphRelationDomainRelateApps\",q,parameter);\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\nvar log = Log.get();\r\nlog.info(res.query);\r\n\r\nvar data = {};\r\ndata.pageNo = pageNo;\r\ndata.pageSize = pageSize;\r\ndata.total = galaxyRes.data.length;\r\ndata.list = new ArrayList();\r\n\r\nvar entityType = \"app\";\r\nfor(key,value in galaxyRes.data){\r\n    resource = value.app_name;\r\n    var entity = {};\r\n    entity.vertex = value.app_name;\r\n    entity.detail = EntityService.queryEntityDetail(entityType,resource).data;\r\n    data.list.add(entity);\r\n}\r\nvar url = db.select(\"select cvalue from sys_config where ckey = \'galaxy_url\'\");\r\nreturn R.ok(data).put(\"originalUrl\",url.cvalue+res.query);');
