    \\\"query\\\": \\\"SELECT DISTINCT(domain) AS domain FROM cn_entity_relation WHERE update_time >= ${startTime} AND update_time < ${endTime} AND cutToFirstSignificantSubdomain(domain) = \\\'${resource}\\\' AND notEmpty(domain) ORDER BY update_time DESC <#if pageSize?default(\\\'\\\')?trim? length gt 0&&pageNo?default(\\\'\\\')?trim? length gt 0> LIMIT ${pageNo},${pageSize}</#if>\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityGraphRelationDomainRelateSubdomains\",q,parameter);\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\nvar log = Log.get();\r\nlog.info(res.query);\r\n\r\nvar data = {};\r\ndata.pageNo = pageNo;\r\ndata.pageSize = pageSize;\r\ndata.total = galaxyRes.data.length;\r\ndata.list = new ArrayList();\r\n\r\nvar entityType = \"domain\";\r\nfor(key,value in galaxyRes.data){\r\n    resource = value.domain;\r\n    var entity = {};\r\n    entity.vertex = value.domain;\r\n    entity.detail = EntityService.queryEntityDetail(entityType,resource).data;\r\n    data.list.add(entity);\r\n}\r\n\r\nvar url = db.select(\"select cvalue from sys_config where ckey = \'galaxy_url\'\");\r\nreturn R.ok(data).put(\"originalUrl\",url.cvalue+res.query);');
