INSERT INTO `magic_api_file` VALUES ('/function/postHandle/npm流量统计地图结果处理.ms', '{\n  \"properties\" : { },\n  \"id\" : \"ded5e552828f445388f87b21e47be384\",\n  \"script\" : null,\n  \"groupId\" : \"f174204de29c472e887e5f3ceccc3f01\",\n  \"name\" : \"npm流量统计地图结果处理\",\n  \"createTime\" : null,\n  \"updateTime\" : 1673854699859,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/npmMapHandle\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"result\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nimport \'@/public/toHump\' as toHump\r\n\r\nif(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(i,j in o.result){\r\n      var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (key,value in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"total_bytes\") != -1){\r\n					tempObj.totalBitsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"total_packets\") != -1){\r\n					tempObj.totalPacketsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj.totalSessionsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj.inboundBitsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj.inboundPacketsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj.outboundBitsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj.outboundPacketsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj.internalBitsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj.internalPacketsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj.throughBitsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj.throughPacketsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj.sessionsRate = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}\r\n 			}\r\n			  //获取countryCodeMap\r\n            var config1 = \"\"\"\r\n            select value from sys_dict where type = \'areaMapping\' and code = \'1\'\r\n            \"\"\"\r\n            var json = db.select(config1);\r\n            var str1 = json.value;\r\n            var index = str1.indexOf(\"{\");\r\n            str1 = str1.substring(index-1);\r\n            var countryCodeMap = str1::json;\r\n			tempObj.serverId = countryCodeMap[tempObj.country];\r\n			\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.province){\r\n					//获取countCityMap\r\n                    var config1 = \"\"\"\r\n                    select value from sys_dict where type = \'areaMapping\' and code = \'2\'\r\n                    \"\"\"\r\n                    var json = db.select(config1);\r\n                    var str2 = json.value;\r\n                    var index = str2.indexOf(\"{\");\r\n                    str2 = str2.substring(index-1);\r\n                    var countCityMap = str2::json;\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.province];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\nreturn result');
INSERT INTO `magic_api_file` VALUES ('/function/postHandle/地图处理.ms', '{\n  \"properties\" : { },\n  \"id\" : \"f4896d21bd7d48c6abfe832cc4df92ac\",\n  \"script\" : null,\n  \"groupId\" : \"f174204de29c472e887e5f3ceccc3f01\",\n  \"name\" : \"地图处理\",\n  \"createTime\" : 1672897818944,\n  \"updateTime\" : 1673402060151,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/mapHandle\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"result\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nimport \'@/public/toHump\' as toHump\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = j;\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = value;\r\n			}\r\n            //获取countryCodeMap\r\n            var config1 = \"\"\"\r\n            select value from sys_dict where type = \'areaMapping\' and code = \'1\'\r\n            \"\"\"\r\n            var json = db.select(config1);\r\n            var str1 = json.value;\r\n            var index = str1.indexOf(\"{\");\r\n            str1 = str1.substring(index-1);\r\n            var countryCodeMap = str1::json;\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountry];\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverProvince){\r\n                    //获取countCityMap\r\n                    var config1 = \"\"\"\r\n                    select value from sys_dict where type = \'areaMapping\' and code = \'2\'\r\n                    \"\"\"\r\n                    var json = db.select(config1);\r\n                    var str2 = json.value;\r\n                    var index = str2.indexOf(\"{\");\r\n                    str2 = str2.substring(index-1);\r\n                    var countCityMap = str2::json;\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverProvince];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\nreturn result');
INSERT INTO `magic_api_file` VALUES ('/function/postHandle/地图处理V2309.ms', '{\n  \"properties\" : { },\n  \"id\" : \"c435f23dde804b8eb09056476f2dda09\",\n  \"script\" : null,\n  \"groupId\" : \"f174204de29c472e887e5f3ceccc3f01\",\n  \"name\" : \"地图处理V2309\",\n  \"createTime\" : null,\n  \"updateTime\" : 1692856587348,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/mapHandleV2309\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"result\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nimport \'@/public/toHump\' as toHump\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = j;\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = value;\r\n			}\r\n            //获取countryCodeMap\r\n            var config1 = \"\"\"\r\n            select value from sys_dict where type = \'areaMapping\' and code = \'1\'\r\n            \"\"\"\r\n            var json = db.select(config1);\r\n            var str1 = json.value;\r\n            var index = str1.indexOf(\"{\");\r\n            str1 = str1.substring(index-1);\r\n            var countryCodeMap = str1::json;\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountryRegion];\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverSuperAdminArea){\r\n                    //获取countCityMap\r\n                    var config1 = \"\"\"\r\n                    select value from sys_dict where type = \'areaMapping\' and code = \'2\'\r\n                    \"\"\"\r\n                    var json = db.select(config1);\r\n                    var str2 = json.value;\r\n                    var index = str2.indexOf(\"{\");\r\n                    str2 = str2.substring(index-1);\r\n                    var countCityMap = str2::json;\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverSuperAdminArea];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\nreturn result');
INSERT INTO `magic_api_file` VALUES ('/function/postHandle/实体关系结果处理.ms', '{\n  \"properties\" : { },\n  \"id\" : \"42b2aabb0a07433ba13c754a091ad6aa\",\n  \"script\" : null,\n  \"groupId\" : \"f174204de29c472e887e5f3ceccc3f01\",\n  \"name\" : \"实体关系结果处理\",\n  \"createTime\" : 1672900388913,\n  \"updateTime\" : 1673341710822,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/relation\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"result\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"parameter\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nimport \'@/public/relation\' as handlerResult\r\n\r\nif(result.success){\r\n	if(parameter.format==1){\r\n		var o={};\r\n		o.resultType=\"relation\";\r\n		o.result={};\r\n		o.result.nodes=[];\r\n		o.result.links=[];\r\n		if(result.data!=undefined&&result.data!=null&&result.data.length>0){\r\n			handlerResult(o,result.data[0]);\r\n		}\r\n		result.data=o;\r\n		result.code=200;\r\n		result.msg = \"\";\r\n		result.message=null;\r\n		var jsonObj = {};\r\n		for(name,value in result){       \r\n			jsonObj[name] = value;\r\n		}\r\n		result = JSON.stringify(jsonObj);\r\n	}else{\r\n		var o={};\r\n		if(result.data!=undefined&&result.data!=null&&result.data.length>0){\r\n			o.resultType=\"relationTree\";\r\n			o.result={};\r\n			o.result.type=result.data[0].type;\r\n			o.result.name=result.data[0].name;\r\n			o.result.leaf=result.data[0].leaf;\r\n		}\r\n		result.data=o;\r\n		result.code=200;\r\n		result.msg = \"\";\r\n		result.message=null;\r\n	}\r\n}\r\nreturn result');
