INSERT INTO `magic_api_file` VALUES ('/function/preHandle/时间处理无转换.ms', '{\n  \"properties\" : { },\n  \"id\" : \"9c995d697d8048f8958eaf11d71e0748\",\n  \"script\" : null,\n  \"groupId\" : \"c054c13da78d46bdb768eaa42d23694b\",\n  \"name\" : \"时间处理无转换\",\n  \"createTime\" : 1672897818972,\n  \"updateTime\" : 1673923226582,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/timeHandleNone\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"parameter\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.Object\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nif (parameter.endTime==\"\" || is_null(parameter.endTime)) {\r\n    parameter.endTime = new Date().getTime()/1000;\r\n}\r\nif (parameter.startTime==\"\" || is_null(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime.asLong() - parameter.startTime.asLong())/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\nparameter.timeDiff = parameter.endTime.asLong() - parameter.startTime.asLong()\r\nreturn parameter');
